CREATE TABLE IF NOT EXISTS orders (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS app_users (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS settlement_requests (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS flower_cache (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS operation_receipts (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sale_aliases (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS deleted_orders (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sync_config (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS app_sessions (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS login_attempts (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS kpi_operations (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS activity_log (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS performance_log (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sync_runs (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sync_cursors (row_key TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX IF NOT EXISTS orders_date_idx ON orders(json_extract(data,'$.order_date'));
CREATE INDEX IF NOT EXISTS orders_request_idx ON orders(json_extract(data,'$.request_id'));
CREATE INDEX IF NOT EXISTS orders_updated_idx ON orders(json_extract(data,'$.updated_at'));
CREATE INDEX IF NOT EXISTS settlement_order_idx ON settlement_requests(json_extract(data,'$.order_id'));
CREATE TABLE IF NOT EXISTS media_chunks (bucket TEXT NOT NULL, object_key TEXT NOT NULL, chunk_no INTEGER NOT NULL, bytes BLOB NOT NULL, content_type TEXT, PRIMARY KEY(bucket,object_key,chunk_no));
